CREATE OR REPLACE FUNCTION public.admin_cleaning_team_options() RETURNS TABLE(pro_id uuid,name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN QUERY SELECT DISTINCT a.contractor_id,concat_ws(' ',a.first_name,a.last_name) FROM public.applicants a WHERE a.contractor_id IS NOT NULL AND NOT coalesce(a.is_test_row,false) AND public.sched_pro_active(a.contractor_id) AND 'cleaning'::public.service_type=ANY(public.sched_pro_services(a.contractor_id)); END $$;
REVOKE ALL ON FUNCTION public.admin_cleaning_team_options() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_cleaning_team_options() TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_cleaning_team(_kind text,_lead uuid,_partner uuid DEFAULT NULL,_helper text DEFAULT NULL,_background boolean DEFAULT false,_insured boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN
 IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF;
 IF _kind NOT IN ('owner_helper','paired_pros') OR _kind IS NULL THEN RAISE EXCEPTION 'invalid_team_kind'; END IF;
 IF _lead IS NULL OR NOT public.sched_pro_active(_lead) OR NOT ('cleaning'::public.service_type=ANY(public.sched_pro_services(_lead))) OR EXISTS(SELECT 1 FROM public.applicants WHERE contractor_id=_lead AND coalesce(is_test_row,false)) THEN RAISE EXCEPTION 'lead_not_assignable'; END IF;
 IF _kind='paired_pros' AND (_partner IS NULL OR _partner=_lead OR NOT public.sched_pro_active(_partner) OR NOT ('cleaning'::public.service_type=ANY(public.sched_pro_services(_partner))) OR EXISTS(SELECT 1 FROM public.applicants WHERE contractor_id=_partner AND coalesce(is_test_row,false))) THEN RAISE EXCEPTION 'partner_not_assignable'; END IF;
 IF _kind='owner_helper' AND (NOT coalesce(_background,false) OR NOT coalesce(_insured,false) OR coalesce(length(trim(_helper)),0)<2 OR length(_helper)>120) THEN RAISE EXCEPTION 'helper_verification_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(_lead::text));
 IF _partner IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtext(_partner::text)); END IF;
 IF EXISTS(SELECT 1 FROM public.cleaning_teams WHERE active AND (lead_pro_id IN (_lead,_partner) OR partner_pro_id IN (_lead,_partner))) THEN RAISE EXCEPTION 'pro_already_in_team'; END IF;
 INSERT INTO public.cleaning_teams(kind,lead_pro_id,partner_pro_id,helper_name,helper_background_checked_at,helper_insurance_verified_at,created_by) VALUES(_kind,_lead,CASE WHEN _kind='paired_pros' THEN _partner END,CASE WHEN _kind='owner_helper' THEN trim(_helper) END,CASE WHEN _background THEN now() END,CASE WHEN _insured THEN now() END,auth.uid()) RETURNING id INTO tid; RETURN tid;
END $$;
CREATE OR REPLACE FUNCTION public.admin_cleaning_staff(_reservation uuid,_team uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reservations; BEGIN IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; IF NOT public.cleaning_team_valid(_team) THEN RAISE EXCEPTION 'team_not_verified'; END IF; SELECT * INTO r FROM public.reservations WHERE id=_reservation FOR UPDATE; IF NOT FOUND OR r.status NOT IN ('reserved','invited') OR r.cleaning_verified_size IS DISTINCT FROM '5' THEN RAISE EXCEPTION 'estate_plus_reservation_required'; END IF; UPDATE public.reservations SET cleaning_team_id=_team,cleaning_team_ready=true,updated_at=now() WHERE id=r.id; END $$;